"""How full each identifier category and block is, warned of before it runs out.

Covers ``MQC_CMN_UNI_112800`` to ``112803``, inventoried in
``docs/design/cmn_verdict_and_cli.md`` section 12 and designed in
``docs/design/harness_test_taxonomy.md`` section 11.9.6.

A failure here is **not a model finding**, so the module carries no priority
marker, per ``framework-rules.md`` section 3.3.
"""

# ------------------------------------------------------------- cases in here
# Generated by `tools/refresh_case_summaries.py`.
#
# TestMQCIdentifierCapacity
#   112800  a_category_at_ninety_assigned_is_warned_of
#   112801  a_block_past_eight_hundred_assigned_is_warned_of
#   112802  a_struck_inventory_row_still_counts_as_assigned
#   112803  this_repository_warns_of_its_own_crowded_blocks
# ------------------------------------------------------------ end of cases

import warnings
from pathlib import Path
from typing import Final

import pytest

from cmn.case_steps import step
from cmn.identifier_capacity import assigned_identifiers, capacity_warnings, select_blocks

pytestmark = pytest.mark.unit

_ROOT: Final[Path] = Path(__file__).resolve().parents[2]


class TestMQCIdentifierCapacity:
    """A crowded category or block is reported while there is still room."""

    def MQC_CMN_UNI_112800_a_category_at_ninety_assigned_is_warned_of(self) -> None:
        """Ninety assigned in one category is warned of; eighty-nine is not.

        Design: ``harness_test_taxonomy.md`` section 11.9.6.

        Returns:
            None
        """
        step(1, "measure a category holding 89 assigned identifiers")
        below = {f"1129{number:02d}" for number in range(89)}
        assert not capacity_warnings(below), capacity_warnings(below)

        step(2, "assign a ninetieth identifier in the same category and measure again")
        reported = capacity_warnings(below | {"112989"})
        assert len(reported) == 1 and "1129xx" in reported[0], reported

    def MQC_CMN_UNI_112801_a_block_past_eight_hundred_assigned_is_warned_of(self) -> None:
        """Eight hundred and one assigned in a block is warned of; eight hundred is not.

        No category reaches ninety, so only the block can be reported.

        Design: ``harness_test_taxonomy.md`` section 11.9.6.

        Returns:
            None
        """
        step(1, "assign 800 identifiers across one block, no category reaching 90")
        full = {f"112{category}{number:02d}" for category in range(8) for number in range(89)}
        full |= {f"1128{number:02d}" for number in range(88)}
        assert len(full) == 800, len(full)

        step(2, "measure the block at 800")
        assert not capacity_warnings(full), capacity_warnings(full)

        step(3, "assign an 801st identifier in the block and measure again")
        reported = capacity_warnings(full | {"112900"})
        assert len(reported) == 1 and "112xxx" in reported[0], reported

    def MQC_CMN_UNI_112802_a_struck_inventory_row_still_counts_as_assigned(
        self, tmp_path: Path
    ) -> None:
        """A retired identifier occupies its slot, so a struck row is counted.

        Design: ``harness_test_taxonomy.md`` section 11.9.6.

        Args:
            tmp_path (Path): A scratch directory.

        Returns:
            None
        """
        step(1, "write a design holding a live row, a struck row and prose naming an identifier")
        design = tmp_path / "design.md"
        design.write_text(
            "| `112901` | P | `a_live_case` |\n"
            "| ~~`112902`~~ | | ~~`a_retired_case`~~. **Retired** |\n"
            "Prose naming `112903` is not an inventory row.\n",
            encoding="utf-8",
        )
        assigned = assigned_identifiers([design])
        assert assigned == {"112901", "112902"}, assigned

    def MQC_CMN_UNI_112803_this_repository_warns_of_its_own_crowded_blocks(self) -> None:
        """The harness's own precondition blocks are measured and warned of, without failing.

        ``1120xx`` holds every one of its hundred numbers and they are never
        reused, so it is warned of for as long as the scheme stands.

        Design: ``harness_test_taxonomy.md`` section 11.9.6.

        Returns:
            None
        """
        step(1, "read every identifier this repository's design inventories assign")
        assigned = select_blocks(
            assigned_identifiers(sorted((_ROOT / "docs" / "design").glob("*.md"))),
            layers="12", modules="1234",
        )
        assert len(assigned) > 500, (
            f"only {len(assigned)} identifiers were read, so the inventories were not"
        )

        step(2, "measure them and raise a warning for each crowded category or block")
        reported = capacity_warnings(assigned)
        for entry in reported:
            warnings.warn(entry, UserWarning, stacklevel=1)
        assert any("1120xx" in entry for entry in reported), (
            f"1120xx, which is full, was not warned of: {reported}"
        )
